(()=>{const q=window.__vmDesktopQa={firstDraw:null,lastDraw:null,drawCalls:0,longTasks:[],lost:0};try{new PerformanceObserver(list=>{for(const e of list.getEntries())if(q.longTasks.length<100)q.longTasks.push({start:e.startTime,duration:e.duration});}).observe({type:'longtask',buffered:true});}catch{}for(const C of [window.WebGLRenderingContext,window.WebGL2RenderingContext])if(C)for(const name of ['drawElements','drawArrays','drawElementsInstanced','drawArraysInstanced']){const original=C.prototype[name];if(typeof original==='function')C.prototype[name]=function(...args){const now=performance.now();q.firstDraw??=now;q.lastDraw=now;q.drawCalls++;return original.apply(this,args);};}document.addEventListener('webglcontextlost',()=>q.lost++,true);})();
